    Хумус с овощами|S|5|Хумус:60;Морковь:80;Огурец:80;Хлебцы:20|Нарезать овощи брусочками.;Подать с хумусом и хлебцами.
    Творожный десерт с какао|S|5|Творог 0%:150;Йогурт греческий:50;Какао-порошок:5;Мёд:10|Взбить творог с йогуртом, какао и мёдом.
    """

    struct Recipe: Identifiable {
        let id: String
        let name: String
        let meal: NutritionMealType
        let minutes: Int
        let ingredients: [(name: String, grams: Double)]
        let steps: [String]
    }

    static let recipes: [Recipe] = {
        raw.split(separator: "\n").compactMap { line -> Recipe? in
            let parts = line.split(separator: "|", omittingEmptySubsequences: false)
                .map { $0.trimmingCharacters(in: .whitespaces) }
            guard parts.count == 5 else { return nil }
            let meal: NutritionMealType
            switch parts[1] {
            case "B": meal = .breakfast
            case "L": meal = .lunch
            case "D": meal = .dinner
            default: meal = .snack
            }
            let ingredients = parts[3].split(separator: ";").compactMap { item -> (String, Double)? in
                let pair = item.split(separator: ":")
                guard pair.count == 2, let grams = Double(pair[1]) else { return nil }
                return (String(pair[0]), grams)
            }
            let steps = parts[4].split(separator: ";").map { String($0).trimmingCharacters(in: .whitespaces) }
            return Recipe(id: parts[0], name: parts[0], meal: meal, minutes: Int(parts[2]) ?? 15,
                          ingredients: ingredients, steps: steps)
        }
    }()
}
